(() => {
  Object.assign(I18N.en,{evidence:'Evidence & purpose',evidenceTitle:'A sound history. A reason to compare.',evidenceSubtitle:'The research behind the prototype, and what remains to be tested.',pairListen:'Listen across visits',pairCurrent:'Selected recording',pairPrevious:'Previous compatible recording',captureSampleDesc:'Up to 20 seconds per site · browser-local storage'});
  Object.assign(I18N.ar,{evidence:'الأدلة والهدف',evidenceTitle:'سجل صوتي يساعد المقارنة.',evidenceSubtitle:'أساس النموذج البحثي وما يحتاج إلى اختبار.',pairListen:'استمع عبر الزيارات',pairCurrent:'التسجيل المحدد',pairPrevious:'التسجيل السابق المتوافق',captureSampleDesc:'حتى 20 ثانية لكل موضع · حفظ محلي في المتصفح'});
  const text=(en,ar)=>lang==='ar'?ar:en;
  const nav=el('button');nav.dataset.view='evidence';nav.onclick=()=>show('evidence');document.querySelector('nav').append(nav);
  const section=el('section','view');section.id='evidence';section.hidden=true;document.querySelector('main').append(section);
  const journey=el('div','evidence-journey');$('history').prepend(journey);
  const protocol=el('p','inline-note');$('captureSite').closest('.form-row').after(protocol);
  const studies=[
    {title:'Song et al. · Scientific Reports · 2023',tag:'40 participants · dedicated acoustic device',url:'https://pubmed.ncbi.nlm.nih.gov/37848465/',finding:'The study reported sensitivity, specificity and accuracy above 90% for detecting stenosis greater than 50% in its dataset.',use:'Supports investigating acoustic features. It does not establish FistulaVoice accuracy, smartphone performance or future-event prediction.'},
    {title:'Poloni et al. · Annals of Biomedical Engineering · 2025',tag:'6 participants · repeated visits · electronic stethoscope',url:'https://pubmed.ncbi.nlm.nih.gov/39485642/',finding:'A prospective study linked acoustic features and their changes over time with ultrasound-based flow measurements and hemodynamic characteristics.',use:'Supports studying longitudinal sound changes. It does not validate our spectral-centroid chart or show that this prototype improves clinical outcomes.'},
    {title:'Higuchi et al. · Japanese Society for Dialysis Therapy · 2023',tag:'3 participants · smartphone recordings',url:'https://www.jstage.jst.go.jp/article/jsdt/56/3/56_117/_article/-char/en',finding:'Fistula sounds were recorded before and after angioplasty in three patients; recordings were louder after the procedure.',use:'An initial feasibility signal. Repeatability across phones, positions and home conditions still needs testing.'}
  ];
  function render(){
    nav.textContent=t('evidence'); journey.replaceChildren();section.replaceChildren();
    const steps=[['01','Record','سجّل','Three fixed sites, with date, device and conditions.','ثلاثة مواضع ثابتة مع التاريخ والجهاز والظروف.','lab'],['02','Compare','قارن','Replay the same site across visits and inspect dated changes.','استمع لنفس الموضع عبر الزيارات وراجع التغيّر بالتاريخ.','history'],['03','Review','راجع','Keep observations with the recording for a later clinical review.','احفظ الملاحظات مع التسجيل للمراجعة السريرية لاحقًا.','recordings']];
    steps.forEach(([n,en,ar,desc,arabic,destination])=>{const b=el('button','evidence-step');b.append(el('span','badge',n),el('strong',null,text(en,ar)),el('span',null,text(desc,arabic)));b.onclick=()=>{if(destination==='history'){historyMode='real';}show(destination);};journey.append(b);});
    const info=el('button','text-button',text('Why this workflow? View the evidence →','لماذا هذه الخطوات؟ اقرأ الأدلة ←'));info.onclick=()=>show('evidence');journey.append(info);
    protocol.textContent=text('Consultation-informed pilot setup: three clinician-agreed sites, approximately 20 seconds each. Record one site at a time using the same device and conditions. This duration is proposed for testing, not a validated clinical standard.','إعداد تجريبي مستند للاستشارة: ثلاثة مواضع يحددها المختص، ونحو 20 ثانية لكل موضع. سجّل كل موضع منفصلًا وبنفس الجهاز والظروف. المدة مقترحة للاختبار وليست معيارًا سريريًا مثبتًا.');
    const purpose=el('article','card evidence-purpose');purpose.append(el('span','badge teal',text('IMPLEMENTED PROTOTYPE','النموذج الحالي')),el('h2',null,text('Keep the sound, not just the description.','احتفظ بالصوت إلى جانب الوصف.')),el('p',null,text('FistulaVoice organizes replayable recordings by access, site and date so a previous observation can be revisited. Guided capture, technical measurements and local review notes demonstrate the proposed workflow.','ينظم FistulaVoice التسجيلات حسب الناسور والموضع والتاريخ للرجوع إلى الملاحظات السابقة. التسجيل الموجّه والقياسات التقنية والملاحظات المحلية توضح سير العمل المقترح.')),el('p','method-note',text('Current: browser-local records. Proposed: secure care-team sharing and clinically validated change detection. No automatic diagnosis or continuous monitoring.','حاليًا: سجل محلي في المتصفح. مستقبلًا: مشاركة آمنة مع الفريق وكشف تغيّر متحقق سريريًا. لا تشخيص آلي أو مراقبة مستمرة.')));section.append(purpose);
    section.append(el('h2',null,text('Research supporting the direction','دراسات تدعم الاتجاه')));
    const grid=el('div','evidence-grid');studies.forEach(s=>{const card=el('article','card evidence-study');card.append(el('p','badge',s.tag),el('h3',null,s.title),el('p',null,s.finding),el('p','inline-note',s.use));const a=el('a','text-button',text('Read the original study ↗','اقرأ الدراسة الأصلية ↗'));a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';card.append(a);grid.append(card);});section.append(grid);
    const next=el('article','card evidence-purpose');next.append(el('h2',null,text('What we need to validate next','ما نحتاج إلى التحقق منه لاحقًا')));const list=el('ol');for(const item of [text('Capture: compare smartphone and electronic-stethoscope recordings.','الالتقاط: مقارنة الهاتف بالسماعة الإلكترونية.'),text('Repeatability: repeat recordings at the same three sites under controlled conditions.','التكرار: إعادة التسجيل في المواضع الثلاثة تحت ظروف مضبوطة.'),text('Usefulness: test whether access to prior sounds helps review and handover, and measure the extra time required.','الفائدة: اختبار أثر الرجوع للصوت السابق على المراجعة والتسليم وقياس الوقت الإضافي.'),text('Future research: link consented longitudinal recordings to ultrasound and clinical outcomes.','البحث المستقبلي: ربط التسجيلات المتتابعة بالموجات فوق الصوتية والنتائج السريرية بعد الموافقات.')])list.append(el('li',null,item));next.append(list,el('p','method-note',text('Research signals are external FiSaV sensor recordings. The demo timeline uses fictional values. Neither is a clinical performance result from FistulaVoice.','الإشارات البحثية تسجيلات حساسات خارجية من FiSaV. الخط الزمني التجريبي يستخدم أرقامًا وهمية. كلاهما ليس نتيجة أداء سريري للنموذج.')));section.append(next);
  }
  new MutationObserver(render).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});render();
  document.querySelector('[data-i18n="captureSampleDesc"]').textContent=t('captureSampleDesc');
})();
